public class InnerServiceLevelObjectiveExclusionWindowFactory(Action<Humidifier.ApplicationSignals.ServiceLevelObjectiveTypes.ExclusionWindow> factoryAction = null) : SubResourceFactory<Humidifier.ApplicationSignals.ServiceLevelObjectiveTypes.ExclusionWindow>
{

    internal InnerServiceLevelObjectiveWindowFactory WindowFactory { get; set; }

    internal InnerServiceLevelObjectiveRecurrenceRuleFactory RecurrenceRuleFactory { get; set; }

    protected override Humidifier.ApplicationSignals.ServiceLevelObjectiveTypes.ExclusionWindow Create()
    {
        var exclusionWindowResult = CreateExclusionWindow();
        factoryAction?.Invoke(exclusionWindowResult);

        return exclusionWindowResult;
    }

    private Humidifier.ApplicationSignals.ServiceLevelObjectiveTypes.ExclusionWindow CreateExclusionWindow()
    {
        var exclusionWindowResult = new Humidifier.ApplicationSignals.ServiceLevelObjectiveTypes.ExclusionWindow();

        return exclusionWindowResult;
    }
    public override void CreateChildren(Humidifier.ApplicationSignals.ServiceLevelObjectiveTypes.ExclusionWindow result)
    {
        base.CreateChildren(result);

        result.Window ??= WindowFactory?.Build();
        result.RecurrenceRule ??= RecurrenceRuleFactory?.Build();
    }

} // End Of Class

